const {
  RESULT_FIXTURES,
  buildSharePayload,
  generateResult,
  getTheme
} = require('../../utils/result-engine');
const { saveResult } = require('../../utils/local-state');
const { track, trackShareClick } = require('../../utils/tracking');

Page({
  data: {
    result: null,
    theme: getTheme(),
    attribution: {},
    posterPath: '',
    posterBusy: false,
    shareCodePath: ''
  },

  onLoad(options) {
    const theme = getTheme(options.theme);
    const attribution = {
      source: options.source || '',
      channel: options.channel || '',
      campaign: options.campaign || ''
    };
    const answerRefs = options.answers ? decodeURIComponent(options.answers).split(',').filter(Boolean) : [];
    const fallbackAnswers = options.type && RESULT_FIXTURES[options.type] ? RESULT_FIXTURES[options.type] : answerRefs;
    const result = generateResult(fallbackAnswers, { themeId: theme.id });
    this.setData({ result, theme, attribution });
    saveResult(result.type, theme.id);

    wx.showShareMenu({
      withShareTicket: true,
      menus: ['shareAppMessage', 'shareTimeline']
    });

    track('result_view', {
      page_name: 'result',
      result_type: result.type,
      theme_id: theme.id,
      result_rarity: result.rarity,
      source_channel: attribution.source || 'direct',
      channel: attribution.channel,
      campaign: attribution.campaign
    });
  },

  onShareAppMessage() {
    const payload = buildSharePayload(this.data.result, 'app_message', this.data.attribution);
    trackShareClick({
      page_name: 'result',
      result_type: this.data.result.type,
      theme_id: this.data.theme.id,
      share_channel: 'app_message',
      channel: this.data.attribution.channel,
      campaign: this.data.attribution.campaign
    });
    const share = {
      title: payload.title,
      path: payload.path
    };
    if (this.data.posterPath) share.imageUrl = this.data.posterPath;
    return share;
  },

  onShareTimeline() {
    const payload = buildSharePayload(this.data.result, 'timeline', this.data.attribution);
    trackShareClick({
      page_name: 'result',
      result_type: this.data.result.type,
      theme_id: this.data.theme.id,
      share_channel: 'timeline',
      channel: this.data.attribution.channel,
      campaign: this.data.attribution.campaign
    });
    const share = {
      title: payload.title,
      query: payload.query
    };
    if (this.data.posterPath) share.imageUrl = this.data.posterPath;
    return share;
  },

  onShareButtonTap() {
    trackShareClick({
      page_name: 'result',
      result_type: this.data.result.type,
      theme_id: this.data.theme.id,
      share_channel: 'button',
      channel: this.data.attribution.channel,
      campaign: this.data.attribution.campaign
    });
  },

  retryQuiz() {
    track('retry_click', {
      page_name: 'result',
      result_type: this.data.result.type,
      theme_id: this.data.theme.id
    });
    wx.redirectTo({ url: `/pages/quiz/quiz?theme=${this.data.theme.id}` });
  },

  openIndex() {
    wx.redirectTo({ url: '/pages/index/index' });
  },

  openAbout() {
    wx.navigateTo({ url: '/pages/about/about' });
  },

  async savePoster() {
    if (this.data.posterBusy) return;
    const result = this.data.result;
    this.setData({ posterBusy: true });
    track('poster_save_click', {
      page_name: 'result',
      result_type: result.type,
      theme_id: this.data.theme.id
    });

    try {
      const shareCodePath = await this.getShareCodePath(result);
      const posterPath = await this.drawPoster(result, shareCodePath);
      this.setData({ posterPath, shareCodePath });
      await this.saveImage(posterPath);
      trackShareClick({
        page_name: 'result',
        result_type: result.type,
        theme_id: this.data.theme.id,
        share_channel: 'poster',
        channel: this.data.attribution.channel,
        campaign: this.data.attribution.campaign
      });
      track('poster_save_success', {
        page_name: 'result',
        result_type: result.type,
        theme_id: this.data.theme.id
      });
      wx.showToast({ title: '已保存' });
    } catch (error) {
      wx.showToast({ title: '保存失败，请重试', icon: 'none' });
    } finally {
      this.setData({ posterBusy: false });
    }
  },

  getShareCodePath(result) {
    if (!wx.cloud) return Promise.resolve('');
    return wx.cloud
      .callFunction({
        name: 'getShareCode',
        data: {
          resultType: result.type,
          themeId: this.data.theme.id
        }
      })
      .then((res) => {
        const fileID = res && res.result && res.result.fileID;
        if (!fileID) return '';
        return wx.cloud.downloadFile({ fileID }).then((download) => download.tempFilePath || '');
      })
      .catch(() => '');
  },

  drawPoster(result, shareCodePath) {
    return new Promise((resolve, reject) => {
      const ctx = wx.createCanvasContext('posterCanvas', this);
      const W = 750;
      const H = 1334;
      ctx.setFillStyle('#FFF8E7');
      ctx.fillRect(0, 0, W, H);
      this.roundRect(ctx, 42, 42, W - 84, H - 84, 18, false, true);
      ctx.setFillStyle('#FFFDF5');
      this.roundRect(ctx, 70, 76, W - 140, H - 152, 14, true, true);

      ctx.setFillStyle('#6B7280');
      ctx.setFontSize(26);
      ctx.setTextAlign('left');
      ctx.fillText('今日打工状态报告', 104, 140);

      ctx.setTextAlign('left');
      ctx.setFillStyle('#171717');
      ctx.setFontSize(70);
      this.drawWrappedText(ctx, result.title, 104, 260, W - 208, 78, 2);
      ctx.setFillStyle('#4B5563');
      ctx.setFontSize(32);
      this.drawWrappedText(ctx, result.oneLiner, 104, 405, W - 208, 46, 2);

      this.drawMeter(ctx, '发疯阈值', result.threshold, 104, 535, result.accent || '#E94B35');
      this.drawMeter(ctx, '电量值', result.battery, 104, 645, '#1F9D55');
      this.drawMeter(ctx, '营业指数', result.businessMode, 104, 755, '#26233A');

      ctx.setFillStyle('#171717');
      ctx.setFontSize(28);
      ctx.fillText('今日保命道具', 104, 905);
      ctx.setFillStyle('#F7EEDC');
      this.roundRect(ctx, 104, 928, W - 208, 74, 10, true, true);
      ctx.setFillStyle('#171717');
      ctx.setFontSize(34);
      ctx.fillText(result.propName, 130, 976);

      ctx.setFontSize(26);
      ctx.fillText('状态标签', 104, 1060);
      this.drawTags(ctx, result.tags.slice(0, 3), 104, 1088);

      ctx.setFillStyle('#2A2A2A');
      ctx.setFontSize(28);
      this.drawWrappedText(ctx, result.posterSlogan, 104, 1190, 390, 40, 2);

      if (shareCodePath) {
        ctx.drawImage(shareCodePath, 540, 1142, 112, 112);
      } else {
        ctx.setStrokeStyle('#171717');
        ctx.strokeRect(540, 1142, 112, 112);
        ctx.setFillStyle('#171717');
        ctx.setFontSize(22);
        ctx.setTextAlign('center');
        ctx.fillText('小程序码', 596, 1205);
        ctx.setTextAlign('left');
      }

      ctx.setFillStyle('#171717');
      this.roundRect(ctx, 104, 1268, W - 208, 48, 8, true, false);
      ctx.setFillStyle('#FFFFFF');
      ctx.setFontSize(24);
      ctx.setTextAlign('center');
      ctx.fillText('测测你今天还剩几格电', W / 2, 1301);

      ctx.draw(false, () => {
        wx.canvasToTempFilePath(
          {
            canvasId: 'posterCanvas',
            width: W,
            height: H,
            destWidth: W,
            destHeight: H,
            success: (res) => resolve(res.tempFilePath),
            fail: reject
          },
          this
        );
      });
    });
  },

  saveImage(filePath) {
    return new Promise((resolve, reject) => {
      wx.saveImageToPhotosAlbum({
        filePath,
        success: resolve,
        fail: reject
      });
    });
  },

  drawMeter(ctx, label, value, x, y, color) {
    const barW = 420;
    ctx.setTextAlign('left');
    ctx.setFillStyle('#171717');
    ctx.setFontSize(28);
    ctx.fillText(label, x, y);
    ctx.setTextAlign('right');
    ctx.setFontSize(34);
    ctx.fillText(`${value}%`, x + 520, y);
    ctx.setFillStyle('#E8DFCF');
    this.roundRect(ctx, x, y + 24, barW, 18, 9, true, false);
    ctx.setFillStyle(color);
    this.roundRect(ctx, x, y + 24, Math.round((barW * value) / 100), 18, 9, true, false);
  },

  drawTags(ctx, tags, x, y) {
    let curX = x;
    tags.forEach((tag) => {
      const text = `#${tag}`;
      const width = Math.min(180, text.length * 25 + 36);
      ctx.setFillStyle('#F7EEDC');
      this.roundRect(ctx, curX, y, width, 48, 6, true, true);
      ctx.setFillStyle('#171717');
      ctx.setFontSize(23);
      ctx.setTextAlign('left');
      ctx.fillText(text, curX + 14, y + 32);
      curX += width + 12;
    });
  },

  drawWrappedText(ctx, text, x, y, maxWidth, lineHeight, maxLines) {
    let line = '';
    let currentY = y;
    let lines = 0;
    for (const char of String(text || '')) {
      const next = line + char;
      if (ctx.measureText(next).width > maxWidth && line) {
        ctx.fillText(line, x, currentY);
        line = char;
        currentY += lineHeight;
        lines += 1;
        if (lines >= maxLines - 1) break;
      } else {
        line = next;
      }
    }
    if (line) ctx.fillText(line, x, currentY);
  },

  roundRect(ctx, x, y, w, h, r, fill, stroke) {
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + w, y, x + w, y + h, r);
    ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r);
    ctx.arcTo(x, y, x + w, y, r);
    ctx.closePath();
    if (fill) ctx.fill();
    if (stroke) {
      ctx.setStrokeStyle('#171717');
      ctx.setLineWidth(3);
      ctx.stroke();
    }
  }
});

