  const copy = RESULTS[type] || RESULTS.low_battery;
  const stats = buildResultStats(copy, scores);
  const theme = getTheme(options.themeId);

  return {
    type,
    title: copy.name,
    name: copy.name,
    oneLiner: copy.oneLiner,
