    unlockHint: copy.unlockHint,
    posterSlogan: copy.posterSlogan,
    shareTitle: pickByHash(copy.shareTitlePool, `${type}:${theme.id}:share`),
    timelineTitle: pickByHash(copy.timelineTitlePool, `${type}:${theme.id}:timeline`),
