function buildSharePayload(result, channel = 'app_message', attribution = {}) {
  const themeId = result.theme?.id || 'general';
  const query = buildQuery({
    source: attribution.source || 'share',
    entry_result: result.type,
    theme: themeId,
    share_channel: channel,
    channel: attribution.channel,
    campaign: attribution.campaign
  });
  return {
    title: channel === 'timeline' ? result.timelineTitle : result.shareTitle,
    path: `/pages/index/index?${query}`,
    query,
    imageUrl: '/assets/share-default.png'
  };
}

function buildResultStats(copy, scores) {
  const threshold = clamp(copy.threshold + Math.round((scores.chaos + scores.social + scores.escape - scores.energy) / 2), 8, 96);
  const battery = clamp(copy.battery + Math.round((scores.energy + scores.focus - scores.escape) / 2), 8, 96);
  const businessMode = clamp(copy.businessMode + Math.round((scores.pretend + scores.social) / 2), 8, 98);
  const percentile = clamp(48 + Math.abs(hashString(`${copy.type}:${threshold}:${battery}`) % 43), 48, 91);
  return { threshold, battery, businessMode, percentile };
}

function toAnswerMap(answerRefs) {
  if (!answerRefs) return {};
  if (!Array.isArray(answerRefs) && typeof answerRefs === 'object') return { ...answerRefs };
  return (answerRefs || []).reduce((answers, ref) => {
    if (!ref) return answers;
    const normalized = String(ref).replace('_', ':');
    const [questionId, answerId] = normalized.split(':');
    if (questionId && answerId) answers[questionId] = answerId;
    return answers;
  }, {});
}

function answerMapToRefs(answers) {
  return Object.keys(answers || {}).map((questionId) => `${questionId}:${answers[questionId]}`);
}

function signatureFromMap(answers) {
  return Object.keys(answers || {})
    .sort((a, b) => Number(a.slice(1)) - Number(b.slice(1)))
    .map((questionId) => `${questionId}:${answers[questionId]}`)
    .join(',');
}

function uniqueQuestions(items) {
  const seen = {};
  return items.filter((item) => {
    if (seen[item.id]) return false;
    seen[item.id] = true;
    return true;
  });
}

function seededShuffle(items, seed) {
  const result = items.slice();
  let state = hashString(seed);
  for (let i = result.length - 1; i > 0; i -= 1) {
    state = (state * 1664525 + 1013904223) >>> 0;
    const j = state % (i + 1);
    const temp = result[i];
    result[i] = result[j];
    result[j] = temp;
  }
  return result;
}

function pickByHash(items, seed) {
  if (!items || !items.length) return '';
  return items[Math.abs(hashString(seed)) % items.length];
}

function buildQuery(params) {
  return Object.keys(params)
    .filter((key) => params[key] !== undefined && params[key] !== null && params[key] !== '')
    .map((key) => `${encodeURIComponent(key)}=${encodeURIComponent(String(params[key]))}`)
    .join('&');
}

function dateSeed(date = new Date()) {
  return `${date.getFullYear()}-${date.getMonth() + 1}-${date.getDate()}`;
}

function hashString(input) {
  let hash = 2166136261;
  for (const ch of String(input)) {
    hash ^= ch.charCodeAt(0);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

module.exports = {
  THEMES,
  RESULT_TYPES,
  RESULT_FIXTURES,
  calculateScores,
  pickQuestionsForTheme,
  selectDailyTheme,
  getTheme,
  generateResult,
  buildSharePayload,
  answerMapToRefs
};

