const fs = require('node:fs');
const path = require('node:path');

const ROOT = path.join(__dirname, '..');

function exists(relPath) {
  return fs.existsSync(path.join(ROOT, relPath));
}

function readProjectConfig() {
  return JSON.parse(fs.readFileSync(path.join(ROOT, 'project.config.json'), 'utf8'));
}

function collectReadiness() {
  const config = readProjectConfig();
  const checks = [
    {
      name: '真实 AppID',
      ok: !!config.appid && config.appid !== 'touristappid',
      detail: config.appid || 'missing'
    },
    {
      name: '小程序根目录',
      ok: config.miniprogramRoot === 'miniprogram/',
      detail: config.miniprogramRoot
    },
    {
      name: '云函数根目录',
      ok: config.cloudfunctionRoot === 'cloudfunctions/',
      detail: config.cloudfunctionRoot
    },
    {
      name: '默认分享图',
      ok: exists('miniprogram/assets/share-default.png'),
      detail: 'miniprogram/assets/share-default.png'
    },
    {
      name: '埋点云函数',
