function getAppVersion() {
  const app = typeof getApp === 'function' ? getApp() : null;
  return app && app.globalData ? app.globalData.appVersion : '0.1.0';
}

function track(eventName, payload) {
  const event = {
    event_name: eventName,
    app_version: getAppVersion(),
    created_at: new Date().toISOString(),
    ...(payload || {})
  };

  if (!wx.cloud) {
    console.info('[track:local]', event);
    return Promise.resolve(event);
  }

  return wx.cloud.callFunction({
    name: 'trackEvent',
    data: { events: [event] }
  }).catch((error) => {
    console.warn('[track:failed]', eventName, error);
    return event;
  });
}

function buildShareClickPayload(payload) {
  return {
    eventName: 'share_click',
    payload: {
      ...(payload || {}),
      share_channel: payload && payload.share_channel ? payload.share_channel : 'button'
    }
  };
}

function trackShareClick(payload) {
  const event = buildShareClickPayload(payload);
  return track(event.eventName, event.payload);
}

module.exports = {
  buildShareClickPayload,
  track,
  trackShareClick
};

