  const second = pickQuestionsForTheme('meeting', '2026-06-02');

  assert.equal(first.length, 8);
  assert.deepEqual(first.map((q) => q.id), second.map((q) => q.id));
  assert.ok(first.some((q) => q.themeIds.includes('meeting')));
});

test('result has complete share, atlas and poster fields', () => {
  const result = generateResult(RESULT_FIXTURES.meeting_drained, { themeId: 'meeting' });

  assert.equal(result.type, 'meeting_drained');
  assert.equal(result.title, '会议耗尽型');
  assert.ok(result.rarityLabel);
  assert.ok(result.oneLiner);
  assert.ok(result.advice);
  assert.ok(result.avoid);
  assert.ok(result.propName);
  assert.ok(result.groupPrompt);
  assert.ok(result.posterSlogan);
  assert.ok(result.timelineTitle);
  assert.equal(result.tags.length, 3);
  assert.ok(result.threshold >= 0 && result.threshold <= 100);
  assert.ok(result.battery >= 0 && result.battery <= 100);
  assert.ok(result.businessMode >= 0 && result.businessMode <= 100);
});

test('empty answer set falls back to low battery result', () => {
  const result = generateResult([], { themeId: 'general' });

  assert.equal(result.type, 'low_battery');
  assert.equal(result.title, '低电量续航型');
});

test('every configured v2 result type can be produced by a fixture', () => {
  assert.equal(RESULT_TYPES.length, 16);

  for (const type of RESULT_TYPES) {
    const result = generateResult(RESULT_FIXTURES[type], { themeId: 'general' });
    assert.equal(result.type, type);
  }
});

test('share payload carries only route context and no user identity', () => {
  const result = generateResult(RESULT_FIXTURES.quiet_crash, { themeId: 'general' });
  const payload = buildSharePayload(result, 'app_message');

  assert.match(payload.title, /静音崩溃型/);
  assert.match(payload.path, /entry_result=quiet_crash/);
  assert.match(payload.path, /theme=general/);
  assert.equal(payload.path.includes('avatar'), false);
  assert.equal(payload.path.includes('nick'), false);
  assert.ok(payload.imageUrl);
});

test('default share image exists in the miniprogram package', () => {
  const imagePath = path.join(__dirname, '..', 'miniprogram', 'assets', 'share-default.png');

  assert.equal(fs.existsSync(imagePath), true);
});

test('share payload preserves attribution context for app message and timeline', () => {
  const result = generateResult(RESULT_FIXTURES.requirement_black_hole, { themeId: 'meeting' });
  const context = {
    source: 'share',
    channel: 'paid_social',
    campaign: 'launch_week',
  };

  const appMessage = buildSharePayload(result, 'app_message', context);
  const timeline = buildSharePayload(result, 'timeline', context);

  assert.match(appMessage.path, /entry_result=requirement_black_hole/);
  assert.match(appMessage.path, /theme=meeting/);
  assert.match(appMessage.path, /source=share/);
  assert.match(appMessage.path, /channel=paid_social/);
  assert.match(appMessage.path, /campaign=launch_week/);
  assert.match(timeline.query, /entry_result=requirement_black_hole/);
  assert.match(timeline.query, /theme=meeting/);
  assert.match(timeline.query, /source=share/);
  assert.match(timeline.query, /channel=paid_social/);
  assert.match(timeline.query, /campaign=launch_week/);
});

test('share click payload uses the unified analytics event name', () => {
  const payload = buildShareClickPayload({
    page_name: 'result',
    result_type: 'low_battery',
    theme_id: 'general',
    share_channel: 'app_message',
  });

  assert.equal(payload.eventName, 'share_click');
  assert.equal(payload.payload.share_channel, 'app_message');
  assert.equal(payload.payload.result_type, 'low_battery');
});

test('openid hash is irreversible and not base64 passthrough', () => {
  const openid = 'mock-openid-123';
  const encoded = Buffer.from(openid).toString('base64');
  const hash = hashOpenId(openid);

  assert.notEqual(hash, encoded);
  assert.match(hash, /^[a-f0-9]{64}$/);
  assert.equal(hashOpenId(''), '');
});

test('share code env version defaults to develop for preview safety', () => {
  assert.equal(normalizeEnvVersion(), 'develop');
  assert.equal(normalizeEnvVersion('trial'), 'trial');
  assert.equal(normalizeEnvVersion('release'), 'release');
  assert.equal(normalizeEnvVersion('bad-value'), 'develop');
});

